def transform(grid):
    h, w = len(grid), len(grid[0])
    separator = grid[4][0]
    step = 5
    block_rows, block_cols = (h + 1) // step, (w + 1) // step

    # Find the distinctive template cell: its colored pattern has more than
    # the four pixels used by the 2x2 color markers in the leftmost cells.
    template = None
    for br in range(block_rows):
        for bc in range(block_cols):
            r0, c0 = br * step, bc * step
            if r0 + 3 >= h or c0 + 3 >= w:
                continue
            pixels = [[grid[r0+i][c0+j] not in (0, separator) for j in range(4)] for i in range(4)]
            if sum(sum(row) for row in pixels) > 4:
                template = pixels
                break
        if template is not None:
            break
    if template is None:
        return [row[:] for row in grid]

    output = [row[:] for row in grid]
    for br in range(block_rows):
        r0 = br * step
        if r0 + 3 >= h:
            continue
        color = grid[r0 + 1][1]
        for bc in range(block_cols):
            c0 = bc * step
            if c0 + 3 >= w:
                continue
            for i in range(4):
                for j in range(4):
                    output[r0+i][c0+j] = color if template[i][j] else 0
    return output
